#define PCKEV_ST4x4_UB(in0, in1, in2, in3, pdst, stride) \
  do {                                                   \
    v16i8 tmp0_m, tmp1_m;                                \
    PCKEV_B2_SB(in1, in0, in3, in2, tmp0_m, tmp1_m);     \
    ST4x4_UB(tmp0_m, tmp1_m, 0, 2, 0, 2, pdst, stride);  \
