#define UPSAMPLE_32PIXELS(a, b, c, d)          \
  do {                                         \
    v16u8 s = __msa_aver_u_b(a, d);            \
    v16u8 t = __msa_aver_u_b(b, c);            \
    const v16u8 st = s ^ t;                    \
    v16u8 ad = a ^ d;                          \
    v16u8 bc = b ^ c;                          \
    v16u8 t0 = ad | bc;                        \
    v16u8 t1 = t0 | st;                        \
    v16u8 t2 = ANDI_B(t1, 1);                  \
    v16u8 t3 = __msa_aver_u_b(s, t);           \
    const v16u8 k = t3 - t2;                   \
    v16u8 diag1, diag2;                        \
    AVER_UB2_UB(t, k, s, k, t0, t1);           \
    bc = bc & st;                              \
    ad = ad & st;                              \
    t = t ^ k;                                 \
    s = s ^ k;                                 \
    t2 = bc | t;                               \
    t3 = ad | s;                               \
    t2 = ANDI_B(t2, 1);                        \
    t3 = ANDI_B(t3, 1);                        \
