#define CLIP_8B_TO_DST(DST, LEFT, TOP, SIZE)                                   \
  do {                                                                         \
    int leftY_1 = ((int)(LEFT)[y] << 16) + (LEFT)[y];                          \
    int temp0, temp1, temp2, temp3;                                            \
