#define WEBP_DSP_INIT(func)                                \
  do {                                                     \
    AcquireSRWLockExclusive(&func##_lock);                 \
    if (func##_last_cpuinfo_used != VP8GetCPUInfo) func(); \
    func##_last_cpuinfo_used = VP8GetCPUInfo;              \
    ReleaseSRWLockExclusive(&func##_lock);                 \
  } while (0)
// clang-format on
